import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"备份与升级","description":"备份 PostgreSQL、对象存储或 local.root、三份 YAML、日志。替换二进制；无独立 migrate CLI。","frontmatter":{"title":"备份与升级","description":"备份 PostgreSQL、对象存储或 local.root、三份 YAML、日志。替换二进制；无独立 migrate CLI。"},"headers":[],"relativePath":"guide/backup.md","filePath":"guide/backup.md","lastUpdated":1790057721000}`),a={name:`guide/backup.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="备份与升级" tabindex="-1">备份与升级 <a class="header-anchor" href="#备份与升级" aria-label="Permalink to “备份与升级”">​</a></h1><h2 id="备份清单" tabindex="-1">备份清单 <a class="header-anchor" href="#备份清单" aria-label="Permalink to “备份清单”">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>位置</th><th>说明</th></tr></thead><tbody><tr><td>元数据</td><td>PostgreSQL</td><td><code>pg_dump</code>；含项目、版本、渠道、会话相关表</td></tr><tr><td>产物</td><td><code>storage.local.root</code> 或 S3/R2 桶</td><td>安装包、差量、清单</td></tr><tr><td>私有对象</td><td><code>storage.private</code></td><td>GeoIP MMDB</td></tr><tr><td>配置</td><td>三份 YAML</td><td>不含进 git 的密钥</td></tr><tr><td>日志</td><td>各 <code>log.file.dir</code></td><td>可选</td></tr></tbody></table><p>恢复时先恢复数据库与对象，再启动同一版本或更新后的二进制。进程启动执行 GORM AutoMigrate，<strong>没有</strong>独立 <code>kirivers migrate</code> 命令。</p><h2 id="升级二进制" tabindex="-1">升级二进制 <a class="header-anchor" href="#升级二进制" aria-label="Permalink to “升级二进制”">​</a></h2><ol><li>备份上表。</li><li>停进程（systemd / 任务计划 / <code>docker stop</code>）。</li><li>替换 Releases 可执行文件或拉取新镜像。官方产物已含管理台，不必再拷前端。</li><li>启动；看 <code>GET /api/v1/health</code>：HTTP 200 且 <code>ready=true</code>（DB + 存储 Head <code>.ready</code>）。</li></ol><p>跨大版本前阅读该次 Release 说明。<code>admin.yaml</code> 的 <code>static_dir</code> 指向管理台静态文件，不是文档站目录。</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};